-- #############################################################################
-- FILE: supabase/migrations/0001_extensions.sql
-- #############################################################################

-- =============================================================================
-- Migration: 0001_extensions.sql
-- Purpose  : Enable Postgres extensions required by the SaaS platform.
-- =============================================================================

-- UUID generation (gen_random_uuid is also available natively via pgcrypto)
create extension if not exists "pgcrypto";

-- Useful for case-insensitive text comparisons later (e.g. emails)
create extension if not exists "citext";


-- #############################################################################
-- FILE: supabase/migrations/0002_helper_functions.sql
-- #############################################################################

-- =============================================================================
-- Migration: 0002_helper_functions.sql
-- Purpose  : Reusable helper functions/triggers shared across every table.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- set_updated_at()
-- Generic trigger function that stamps NEW.updated_at with the current time
-- on every UPDATE. Attached per-table in each table's migration file so that
-- no application code is ever responsible for maintaining updated_at.
-- -----------------------------------------------------------------------------
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

comment on function public.set_updated_at() is
  'Trigger function: sets NEW.updated_at = now() on every row update. Attach via
   "create trigger trg_<table>_updated_at before update on <table> for each row
   execute function public.set_updated_at();"';


-- #############################################################################
-- FILE: supabase/migrations/0003_saas_admins.sql
-- #############################################################################

-- =============================================================================
-- Migration: 0003_saas_admins.sql
-- Purpose  : Platform-level administrators who control the entire SaaS system.
--            These are NOT store users. Authentication is custom (see docs).
-- =============================================================================

create table if not exists public.saas_admins (
  id                  uuid primary key default gen_random_uuid(),

  login_id            citext not null,
  password_hash       text not null,

  full_name           text not null,
  phone               text,

  status              text not null default 'active'
                       check (status in ('active', 'disabled')),

  last_login_at       timestamptz,

  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),

  constraint saas_admins_login_id_key unique (login_id)
);

comment on table public.saas_admins is
  'Platform-level administrators. Distinct from store_users. Custom auth only — no Supabase Auth.';
comment on column public.saas_admins.password_hash is
  'Argon2id/bcrypt hash produced by a trusted server-side function. Never store or compare plain text.';

create index if not exists idx_saas_admins_status on public.saas_admins (status);

create trigger trg_saas_admins_updated_at
  before update on public.saas_admins
  for each row
  execute function public.set_updated_at();

-- Row Level Security: the anon/public key must never be able to read or write
-- this table directly. All access happens through trusted server-side
-- functions using the service role, which bypasses RLS by design. Enabling
-- RLS here with no permissive policies means the anon/authenticated roles are
-- hard-blocked at the database layer as defense-in-depth.
alter table public.saas_admins enable row level security;
-- Intentionally no policies are created: default-deny for anon/authenticated.


-- #############################################################################
-- FILE: supabase/migrations/0004_store_code_sequence.sql
-- #############################################################################

-- =============================================================================
-- Migration: 0004_store_code_sequence.sql
-- Purpose  : Concurrency-safe generation of human-readable Store IDs
--            (e.g. STORE-0001, STORE-0002, ...) using a real Postgres SEQUENCE.
--            A sequence guarantees no two concurrent store-creation requests
--            can ever receive the same number, without needing application-side
--            locking or "select max()+1" races.
-- =============================================================================

create sequence if not exists public.store_code_seq
  as bigint
  start with 1
  increment by 1
  no cycle;

-- -----------------------------------------------------------------------------
-- generate_store_code()
-- Returns the next formatted store code, e.g. 'STORE-0001'.
-- Padding is 4 digits by default; once the sequence exceeds 9999 the code
-- simply grows to 'STORE-10000', etc. Centralizing the format here means the
-- prefix/padding can be changed later in one place without touching app code.
-- -----------------------------------------------------------------------------
create or replace function public.generate_store_code()
returns text
language plpgsql
as $$
declare
  next_val bigint;
begin
  next_val := nextval('public.store_code_seq');
  return 'STORE-' || lpad(next_val::text, 4, '0');
end;
$$;

comment on function public.generate_store_code() is
  'Concurrency-safe next human-readable store code, e.g. STORE-0001. Backed by a
   real sequence so simultaneous store creations never collide. Call this only
   from trusted server-side store-creation logic, never from the browser.';


-- #############################################################################
-- FILE: supabase/migrations/0005_stores.sql
-- #############################################################################

-- =============================================================================
-- Migration: 0005_stores.sql
-- Purpose  : The tenant table. Every store is one clothing-store business
--            using the SaaS platform. All future business tables hang off
--            store_id (see 0999_tenant_convention_notes.sql).
-- =============================================================================

create table if not exists public.stores (
  id                  uuid primary key default gen_random_uuid(),

  -- Human-readable identifier, e.g. STORE-0001. Generated server-side via
  -- generate_store_code(); never used as a primary/foreign key.
  store_code          text not null default public.generate_store_code(),

  business_name       text not null,
  legal_name          text,

  owner_name          text not null,
  mobile              text not null,
  whatsapp            text,
  email                citext,

  address_line_1      text not null,
  address_line_2      text,
  city                text,
  state               text,
  country             text not null,
  postal_code         text,

  currency_code       text not null default 'QAR',
  timezone            text not null default 'Asia/Qatar',
  tax_number          text,

  logo_url            text,

  -- Soft-deletion lifecycle. Stores are archived, never hard-deleted, so that
  -- historical business records (invoices, audit logs, etc.) remain valid.
  status              text not null default 'active'
                       check (status in ('active', 'suspended', 'inactive', 'archived')),

  created_by          uuid references public.saas_admins (id) on delete set null,

  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),

  constraint stores_store_code_key unique (store_code),
  constraint stores_currency_code_len check (char_length(currency_code) = 3)
);

comment on table public.stores is
  'Tenant table. One row per clothing-store business on the SaaS platform.';
comment on column public.stores.store_code is
  'Human-readable ID (STORE-0001). Display/reference only — never a FK target.';
comment on column public.stores.status is
  'active | suspended | inactive | archived. Stores are archived, never hard-deleted.';

create index if not exists idx_stores_store_code on public.stores (store_code);
create index if not exists idx_stores_status on public.stores (status);

create trigger trg_stores_updated_at
  before update on public.stores
  for each row
  execute function public.set_updated_at();

alter table public.stores enable row level security;
-- No anon/authenticated policies: all reads/writes go through trusted
-- server-side endpoints that use the service role and enforce tenant
-- authorization from a validated session (see docs/ARCHITECTURE.md).


-- #############################################################################
-- FILE: supabase/migrations/0006_roles_permissions.sql
-- #############################################################################

-- =============================================================================
-- Migration: 0006_roles_permissions.sql
-- Purpose  : Role-based access control foundation.
--            - roles: either a system role (store_id is null) reusable across
--              all stores as a template, or a store-specific role.
--            - permissions: the fixed catalogue of fine-grained capabilities.
--            - role_permissions: join table assigning permissions to roles.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- roles
-- -----------------------------------------------------------------------------
create table if not exists public.roles (
  id                  uuid primary key default gen_random_uuid(),

  -- NULL store_id => system/template role (e.g. a default "Store Admin"
  -- template maintained by the SaaS platform). Non-null => a role that
  -- belongs to, and is only usable within, that specific store.
  store_id            uuid references public.stores (id) on delete cascade,

  name                text not null,
  description         text,

  is_system_role      boolean not null default false,

  status              text not null default 'active'
                       check (status in ('active', 'disabled')),

  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),

  -- A role name must be unique within its scope (per store, or among the
  -- global system roles when store_id is null).
  constraint roles_store_name_key unique (store_id, name)
);

comment on table public.roles is
  'RBAC roles. store_id NULL = platform/system template role. store_id set = store-owned role.';

create index if not exists idx_roles_store_id on public.roles (store_id);
create index if not exists idx_roles_status on public.roles (status);

create trigger trg_roles_updated_at
  before update on public.roles
  for each row
  execute function public.set_updated_at();

alter table public.roles enable row level security;

-- -----------------------------------------------------------------------------
-- permissions
-- -----------------------------------------------------------------------------
create table if not exists public.permissions (
  id                  uuid primary key default gen_random_uuid(),

  -- e.g. 'sales.create'
  permission_key      text not null,
  module              text not null,
  action               text not null,
  description         text,

  created_at          timestamptz not null default now(),

  constraint permissions_permission_key_key unique (permission_key)
);

comment on table public.permissions is
  'Fixed catalogue of fine-grained permission keys, e.g. sales.create, inventory.adjust.';

create index if not exists idx_permissions_module on public.permissions (module);

alter table public.permissions enable row level security;

-- -----------------------------------------------------------------------------
-- role_permissions
-- -----------------------------------------------------------------------------
create table if not exists public.role_permissions (
  id                  uuid primary key default gen_random_uuid(),

  role_id             uuid not null references public.roles (id) on delete cascade,
  permission_id       uuid not null references public.permissions (id) on delete cascade,

  created_at          timestamptz not null default now(),

  constraint role_permissions_role_permission_key unique (role_id, permission_id)
);

comment on table public.role_permissions is
  'Join table: which permissions are granted to which role.';

create index if not exists idx_role_permissions_role_id on public.role_permissions (role_id);
create index if not exists idx_role_permissions_permission_id on public.role_permissions (permission_id);

alter table public.role_permissions enable row level security;


-- #############################################################################
-- FILE: supabase/migrations/0007_store_users.sql
-- #############################################################################

-- =============================================================================
-- Migration: 0007_store_users.sql
-- Purpose  : Users that belong to a specific store (cashiers, managers, etc).
--            Custom auth: login_id + password_hash, scoped uniquely per store.
-- =============================================================================

create table if not exists public.store_users (
  id                     uuid primary key default gen_random_uuid(),

  store_id               uuid not null references public.stores (id) on delete cascade,

  login_id               citext not null,
  password_hash          text not null,

  full_name              text not null,
  phone                  text,

  -- Prefer disabling a role over deleting it while users depend on it
  -- (enforced procedurally in Phase 2/3 application logic; see roles table).
  role_id                uuid references public.roles (id) on delete set null,

  status                 text not null default 'active'
                          check (status in ('active', 'disabled', 'locked')),

  -- Brute-force protection fields, used by the Phase 2 login endpoint.
  failed_login_attempts  integer not null default 0,
  locked_until           timestamptz,

  password_changed_at    timestamptz not null default now(),
  last_login_at          timestamptz,

  created_by             uuid references public.store_users (id) on delete set null,

  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),

  -- Username only needs to be unique WITHIN a store, so STORE-0001/admin and
  -- STORE-0002/admin can coexist, but STORE-0001/admin cannot be duplicated.
  constraint store_users_store_login_key unique (store_id, login_id)
);

comment on table public.store_users is
  'Users belonging to a single store. login_id is unique per store_id, not globally.';
comment on column public.store_users.password_hash is
  'Argon2id/bcrypt hash produced by a trusted server-side function. Never store or compare plain text.';

create index if not exists idx_store_users_store_id on public.store_users (store_id);
create index if not exists idx_store_users_store_login on public.store_users (store_id, login_id);
create index if not exists idx_store_users_status on public.store_users (status);
create index if not exists idx_store_users_role_id on public.store_users (role_id);

create trigger trg_store_users_updated_at
  before update on public.store_users
  for each row
  execute function public.set_updated_at();

alter table public.store_users enable row level security;
-- No anon/authenticated policies: reads/writes only via trusted server-side
-- endpoints. The application layer is responsible for scoping every query by
-- the store_id resolved from a verified session (never from client input).


-- #############################################################################
-- FILE: supabase/migrations/0008_sessions.sql
-- #############################################################################

-- =============================================================================
-- Migration: 0008_sessions.sql
-- Purpose  : Server-managed session storage for the custom auth system.
--
-- DESIGN DECISION (documented per Phase-1 spec §15):
-- We use TWO separate, strongly-typed session tables instead of one
-- polymorphic "user_sessions" table with a nullable user_id/admin_id pair.
--
-- Why:
--   - A single polymorphic table (user_id + session_type discriminator, no
--     real FK) cannot enforce referential integrity at the database level —
--     a bad session_type or mismatched id would silently point nowhere.
--   - saas_admins and store_users are different entities with different
--     lifecycles, blast radii, and security sensitivity (a platform-admin
--     session compromise is far more severe than a single store's cashier
--     session). Keeping them in separate tables makes it impossible for a
--     bug to accidentally treat one kind of session as the other.
--   - Real foreign keys + real CASCADE behavior are available on both
--     tables, which is not possible with a single polymorphic user_id column.
--
-- A thin view (public.v_all_sessions) is provided below for the rare cases
-- (admin dashboards, audit tooling) that want a unified read-only look
-- across both tables.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- store_user_sessions
-- -----------------------------------------------------------------------------
create table if not exists public.store_user_sessions (
  id                  uuid primary key default gen_random_uuid(),

  store_user_id       uuid not null references public.store_users (id) on delete cascade,
  store_id            uuid not null references public.stores (id) on delete cascade,

  -- Only a SHA-256 (or similar) hash of the opaque session token is stored.
  -- The raw token is returned to the client exactly once at login time and
  -- never persisted server-side.
  token_hash          text not null,

  created_at          timestamptz not null default now(),
  expires_at          timestamptz not null,
  last_activity_at    timestamptz not null default now(),
  revoked_at          timestamptz,

  ip_address          text,
  user_agent          text,
  device_name         text,

  constraint store_user_sessions_token_hash_key unique (token_hash)
);

comment on table public.store_user_sessions is
  'Server-side sessions for store_users. Only a hash of the session token is stored.';

create index if not exists idx_store_user_sessions_user_id on public.store_user_sessions (store_user_id);
create index if not exists idx_store_user_sessions_store_id on public.store_user_sessions (store_id);
create index if not exists idx_store_user_sessions_token_hash on public.store_user_sessions (token_hash);
create index if not exists idx_store_user_sessions_expires_at on public.store_user_sessions (expires_at);

alter table public.store_user_sessions enable row level security;

-- -----------------------------------------------------------------------------
-- saas_admin_sessions
-- -----------------------------------------------------------------------------
create table if not exists public.saas_admin_sessions (
  id                  uuid primary key default gen_random_uuid(),

  saas_admin_id       uuid not null references public.saas_admins (id) on delete cascade,

  token_hash          text not null,

  created_at          timestamptz not null default now(),
  expires_at          timestamptz not null,
  last_activity_at    timestamptz not null default now(),
  revoked_at          timestamptz,

  ip_address          text,
  user_agent          text,
  device_name         text,

  constraint saas_admin_sessions_token_hash_key unique (token_hash)
);

comment on table public.saas_admin_sessions is
  'Server-side sessions for saas_admins. Only a hash of the session token is stored.';

create index if not exists idx_saas_admin_sessions_admin_id on public.saas_admin_sessions (saas_admin_id);
create index if not exists idx_saas_admin_sessions_token_hash on public.saas_admin_sessions (token_hash);
create index if not exists idx_saas_admin_sessions_expires_at on public.saas_admin_sessions (expires_at);

alter table public.saas_admin_sessions enable row level security;

-- -----------------------------------------------------------------------------
-- Unified read-only view (optional convenience for cross-cutting tooling).
-- session_type mirrors the "session_type" concept requested in the spec
-- while keeping the underlying storage strongly typed and normalized.
-- -----------------------------------------------------------------------------
create or replace view public.v_all_sessions as
select
  id,
  'store_user'::text as session_type,
  store_user_id as principal_id,
  store_id,
  token_hash,
  created_at,
  expires_at,
  last_activity_at,
  revoked_at,
  ip_address,
  user_agent,
  device_name
from public.store_user_sessions
union all
select
  id,
  'saas_admin'::text as session_type,
  saas_admin_id as principal_id,
  null::uuid as store_id,
  token_hash,
  created_at,
  expires_at,
  last_activity_at,
  revoked_at,
  ip_address,
  user_agent,
  device_name
from public.saas_admin_sessions;

comment on view public.v_all_sessions is
  'Read-only union of store_user_sessions and saas_admin_sessions for cross-cutting tooling/audits.';


